sections.body:
A **Descriptor** is an object that defines how attribute access works. When Python sees `obj.attr`, it checks if `attr` is a descriptor on the class. Descriptors power `@property`, `@classmethod`, `@staticmethod` — they're all descriptors!

```
DESCRIPTOR = Object that defines:
  __get__    → called on attribute READ
  __set__    → called on attribute WRITE
  __delete__ → called on attribute DELETE

Data Descriptor    = defines __get__ + __set__ (or __delete__)
Non-Data Descriptor= defines only __get__
```

```python name=descriptors_complete.py
# ══════════════════════════════════════════════════
#  DESCRIPTORS — The mechanism behind @property
# ══════════════════════════════════════════════════

# ─── Basic Descriptor ───
class Validator:
    """
    Reusable validation descriptor.
    Can be used as a class attribute on ANY model class.
    """
    def __init__(self, min_val=None, max_val=None,
                 type_=None, required=True):
        self.min_val  = min_val
        self.max_val  = max_val
        self.type_    = type_
        self.required = required
        self.name     = None   # set by __set_name__

    def __set_name__(self, owner, name):
        """Called when descriptor is assigned to class attribute"""
        self.name         = name
        self.private_name = f"_{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self   # accessed on class, not instance
        return getattr(obj, self.private_name, None)

    def __set__(self, obj, value):
        self._validate(value)
        setattr(obj, self.private_name, value)

    def __delete__(self, obj):
        delattr(obj, self.private_name)

    def _validate(self, value):
        if self.required and value is None:
            raise ValueError(f"'{self.name}' is required")
        if value is None:
            return
        if self.type_ and not isinstance(value, self.type_):
            raise TypeError(
                f"'{self.name}' must be {self.type_.__name__}, "
                f"got {type(value).__name__}"
            )
        if self.min_val is not None and value < self.min_val:
            raise ValueError(f"'{self.name}' must be >= {self.min_val}")
        if self.max_val is not None and value > self.max_val:
            raise ValueError(f"'{self.name}' must be <= {self.max_val}")

# ─── Using Descriptor as class attribute ───
class Product:
    # Descriptors replace @property for REUSABLE validation!
    name     = Validator(type_=str)
    price    = Validator(type_=(int, float), min_val=0)
    stock    = Validator(type_=int, min_val=0, max_val=100000)
    discount = Validator(type_=(int, float), min_val=0, max_val=100, required=False)

    def __init__(self, name, price, stock, discount=0):
        self.name     = name      # calls Validator.__set__!
        self.price    = price
        self.stock    = stock
        self.discount = discount

    def __repr__(self):
        return f"Product({self.name}, ₹{self.price}, stock={self.stock})"

class Employee:
    # Same descriptors — reused on a completely different class!
    name   = Validator(type_=str)
    age    = Validator(type_=int, min_val=18, max_val=70)
    salary = Validator(type_=(int,float), min_val=15000)

    def __init__(self, name, age, salary):
        self.name   = name
        self.age    = age
        self.salary = salary

print("=== Descriptors: Reusable Validation ===")
p = Product("Laptop", 75000, 50, 10)
print(p)

# Validation triggers
test_cases = [
    lambda: Product("", 100, 10),          # empty name
    lambda: Product("X", -500, 10),        # negative price
    lambda: Product("X", 100, -5),         # negative stock
    lambda: Product(123, 100, 10),         # wrong type for name
]
for tc in test_cases:
    try:
        tc()
    except (ValueError, TypeError) as e:
        print(f"  ❌ {e}")

print("\n=== Same Validator on Employee ===")
emp = Employee("Alice", 28, 75000)
print(f"  {emp.name}, {emp.age}, ₹{emp.salary}")
try:
    Employee("Bob", 15, 50000)   # underage!
except ValueError as e:
    print(f"  ❌ {e}")

# ─── Non-Data Descriptor: Lazy Property ───
class lazy_property:
    """
    Computes value on first access, then stores in instance dict.
    Same as @functools.cached_property — but let's build it ourselves!
    """
    def __init__(self, func):
        self.func = func
        self.name = func.__name__

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        # Compute and store in instance __dict__
        # Next access reads from __dict__ directly (bypasses descriptor!)
        value = self.func(obj)
        obj.__dict__[self.name] = value
        print(f"  💾 Computed and cached: {self.name}")
        return value

class Report:
    def __init__(self, data):
        self.data = data

    @lazy_property
    def total(self):
        import time; time.sleep(0.05)  # expensive computation
        return sum(self.data)

    @lazy_property
    def average(self):
        return sum(self.data) / len(self.data)

    @lazy_property
    def max_value(self):
        return max(self.data)

print("\n=== Lazy Property Descriptor ===")
rpt = Report(list(range(1, 1001)))
print(f"Total   (1st access): {rpt.total}")     # computed
print(f"Total   (2nd access): {rpt.total}")     # from __dict__, NO print!
print(f"Average             : {rpt.average}")
print(f"Max                 : {rpt.max_value}")
